    "key": "oct1030",
    "date": "2026.10.30",
    "period": "2026年10月",
    "folder": "1030 他说错了什么？",
    "titleZh": "他说错了什么？",
    "title": "Soccer star Kylian Mbappé apologizes for apparent reference to Mao as a 'dictator'",
    "topicEn": "Economics",
    "topicZh": "经济",
    "byline": "By E. Eduardo Castillo, AP News, Updated October 28, 2026",
    "paragraphs": [
      "Soccer star Kylian Mbappé apologized for comments in which he apparently referred to Mao, the founding leader of Communist China, as a dictator, after facing backlash and losing brand deals with at least three different Chinese companies.",
      "“My comment was ill-judged, and I now understand that it hurt many people in China and in Chinese communities around the world,” Mbappé said in a statement Tuesday.",
      "“I apologize to everyone my words have upset,” he said. “This was absolutely not my intention. I have deep respect for the Chinese people and their history, and I am sincerely sorry.”",
      "The incident is the latest in a string of cases in which China has leveraged its economic clout to compel foreign companies and individuals to apologize for perceived slights. In 2019, Chinese state television ceased broadcasting NBA games after then-Houston Rockets general manager Daryl Morey tweeted support for anti-government protesters in HK.",
      "Backlash has been swift and harsh",
      "Mbappé’s face has appeared in ads across China, from subway stations to inside elevators.",
      "Beverage maker Dongpeng, dairy giant Mengniu and cheese maker Milkground said in similarly worded statements Tuesday that they were ending agreements with the soccer star, each saying they oppose “any words and actions that hurt national sentiment.”",
      "The companies did not specify what prompted their decisions, but they released their statements after a clip that appeared to show Mbappé being interviewed ahead of going on the French online talk show “The Bridge” circulated on X.",
      "The China Football Association said in a statement Tuesday that it has “lodged a stern protest” with Real Madrid and demanded that both the player and the football club “issue a public and formal apology.”",
      "The association stressed it firmly opposes “any remarks that hurt the feelings of the Chinese people.”",
      "China Media Group also said that it has suspended broadcasts of matches in the Spanish league, La Liga, and other games featuring the French soccer star, and removed advertisements featuring him. The media conglomerate demanded an apology from Mbappé and his club, Real Madrid.",
      "The Spanish league was quick to try to protect its television business in China. It said in a statement that it “deeply regrets the offense caused to Chinese fans by Mbappé’s recent comments. These remarks were made in a personal capacity and do not represent La Liga.”",
      "The league said it would create a “communication protocol” for its players and clubs while working with stakeholders in China to prevent any future incidents.",
      "Spanish league president Javier Tebas later Tuesday said on X that he met with China’s ambassador to Spain, Yao Jing, to address the fallout from Mbappé’s remarks and seek a resolution. Tebas stressed La Liga’s commitment to preserving its partnerships with China, including its strategic agreement with the Chinese league through 2029 and deals with China Media Group. “Our commitment is to keep working together so that an individual episode does not harm the important advances achieved nor affect the millions of Chinese fans who follow our competitions. China is and will continue to be a strategic partner for La Liga,” Tebas said."
    ],
    "paragraphTranslations": [
      "足球明星基利安·姆巴佩就其言论道歉，他在言论中显然将中 G 创始 LD 人 Mao 称为“独 cai 者”。此前，他遭到舆论强烈抵制，至少有 3 家中国企业终止了与他的品牌合作。",
      "姆巴佩周二在一份声明中说：“我的言论欠妥，如今我明白，这些话伤害了中国以及世界各地华人社区的许多人。”",
      "“我向所有被我的言论所伤害的人道歉。”他说，“这绝非我的本意。我对中国人民及其历史怀有深深的敬意，我真心感到抱歉。”",
      "该起事件是近年来中国利用其经济影响力，迫使外国公司和个人为所谓的冒犯行为道歉的最新案例。2019 年，时任休斯敦火箭队总经理达雷尔·莫雷在社交平台发推支持 HK 的反 zheng 府抗议者后，中国国家电视台停止转播 NBA 比赛。",
      "抵制浪潮来得迅速而猛烈",
      "从地铁站到电梯间，中国各地的广告中都能看到姆巴佩的身影。",
      "饮料生产商东鹏饮料、乳业巨头蒙牛以及奶酪生产商妙可蓝多周二发布了措辞相似的声明，宣布终止与这位足球明星的合作。三家公司均表示，反对“任何伤害民族感情的言行”。",
      "三家公司没有具体说明作出这一决定的原因。但在一段显示姆巴佩在参加法国在线脱口秀节目“The Bridge”之前接受采访的视频在 X 上流传之后，他们发表了声明。",
      "中国足球协会周二发表声明称，已向皇家马德里俱乐部提出“严正抗议”，并要求姆巴佩本人和俱乐部“公开、正式地道歉”。",
      "中国足协强调，坚决反对“任何伤害中国人民感情的言论”。",
      "中央广播电视总台也表示，已暂停转播西甲联盟的比赛以及其他有姆巴佩参加的赛事，并撤下了包含其形象的广告。该传媒巨头要求姆巴佩及其所属俱乐部皇家马德里作出道歉。",
      "西甲联盟很快作出回应，试图保护其在中国的电视转播业务。联盟在一份声明中表示：“对于姆巴佩近期言论冒犯中国球迷一事，我们深表遗憾。这些言论仅代表其个人立场，并不代表西甲联盟。”",
      "西甲联盟还表示，将与中国相关各方合作，为球员和俱乐部建立一套沟通机制，以防止类似事件再次发生。",
      "周二晚些时候，西甲联盟主席哈维尔·特巴斯在 X 平台上表示，他已与中国驻西班牙大使姚敬会面，讨论姆巴佩言论引发的后续影响，并寻求解决办法。特巴斯强调，西甲将继续致力于维护与中国的合作关系，其中包括与中国足球联赛签订的、有效期至 2029 年的战略协议，以及与中央广播电视总台达成的合作协议。\n\n特巴斯说：“我们承诺将继续携手合作，不让个别事件损害双方已经取得的重要进展，也不让这一事件影响数百万关注西甲赛事的中国球迷。中国现在是、今后也将继续是西甲的重要战略合作伙伴。”"
    ],
