    "exerciseTranslationPrompt": "这种飞速更迭、充满不确定性的环境，才是大学生做选择时应当考量、应当去适应的。最稳妥的办法，不是紧盯当下看起来实用的东西，而是去学习那些具备长久价值的内容——那些不受任何技术限制、不会随潮流过时的东西。",
